CREATE TABLE "credential_input_sources" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "created_at" timestamptz NOT NULL, "updated_at" timestamptz NOT NULL, "input_id" character varying NOT NULL, "metadata" jsonb NULL, "credential_input_sources" bigint NOT NULL, "credential_sourced_by" bigint NOT NULL, PRIMARY KEY ("id"), CONSTRAINT "credential_input_sources_credentials_input_sources" FOREIGN KEY ("credential_input_sources") REFERENCES "credentials" ("id") ON DELETE CASCADE, CONSTRAINT "credential_input_sources_credentials_sourced_by" FOREIGN KEY ("credential_sourced_by") REFERENCES "credentials" ("id") ON DELETE CASCADE);
CREATE UNIQUE INDEX "credentialinputsource_input_id_credential_input_sources" ON "credential_input_sources" ("input_id", "credential_input_sources");
